@page "/dashboard"
@rendermode InteractiveServer
@inject Services.InventoryAlertService AlertService
@inject Services.WarehouseState WarehouseState
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Current Warehouse</h5>
                <p class="card-text fs-4">@GetWarehouseName()</p>
            </div>
        </div>
    </div>
    <div class="col-md-6">
        <div class="card @(AlertService.CurrentLowStockCount > 5 ? "border-danger" : "border-success")">
            <div class="card-body">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="card-text fs-1 @(AlertService.CurrentLowStockCount > 5 ? "text-danger" : "text-success")">
                    @AlertService.CurrentLowStockCount
                </p>
                <p class="card-text text-muted">
                    Items below minimum level &bull; refreshes every 10s
                </p>
            </div>
        </div>
    </div>
</div>

<div class="alert alert-info">
    <strong>Polling status:</strong> Active &mdash; checking for low stock items every 10 seconds for
    <em>@GetWarehouseName()</em>.
</div>

@code {
    private Action? _alertHandler;
    private Action? _warehouseHandler;

    protected override void OnInitialized()
    {
        _alertHandler = () => InvokeAsync(StateHasChanged);
        _warehouseHandler = () => InvokeAsync(StateHasChanged);

        AlertService.OnAlertCountChanged += _alertHandler;
        WarehouseState.OnChange += _warehouseHandler;

        // Start polling when this page becomes visible
        AlertService.StartPolling();
    }

    private string GetWarehouseName()
    {
        var wh = Services.WarehouseState.AvailableWarehouses
            .FirstOrDefault(w => w.Id == WarehouseState.CurrentWarehouseId);
        return wh == default ? WarehouseState.CurrentWarehouseId : wh.Name;
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= _alertHandler;
        WarehouseState.OnChange -= _warehouseHandler;

        // Stop polling when leaving the dashboard
        AlertService.StopPolling();
    }
}

